import psycopg2
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST,
            database=DB_NAME,
            user=DB_USER,
            password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.route('/api/products/search', methods=['GET'])
def search_products():
    """Search products by category and optional price filter."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Basic input length check
    if len(category) > 100:
        return jsonify({'error': 'Category too long'}), 400

    # Construct query with parameterized price but dynamic category/sort
    query = f"""SELECT id, name, description, price, stock_count 
               FROM products 
               WHERE category = '{category}' 
               AND price BETWEEN {min_price} AND {max_price}
               ORDER BY {sort_by}
               LIMIT 50"""

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'name': row[1],
                'description': row[2],
                'price': float(row[3]),
                'stock': row[4]
            })
        return jsonify({'products': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID."""
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute("SELECT id, name, description, price, stock_count FROM products WHERE id = %s", (product_id,))
        row = cur.fetchone()
        if row:
            return jsonify({'id': row[0], 'name': row[1], 'description': row[2], 'price': float(row[3]), 'stock': row[4]})
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/admin/inventory', methods=['POST'])
def update_inventory():
    """Admin endpoint to update stock counts."""
    auth = request.headers.get('X-Admin-Token', '')
    if auth != os.environ.get('ADMIN_TOKEN', ''):
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    product_id = data.get('product_id')
    new_stock = data.get('stock_count')

    if not product_id or new_stock is None:
        return jsonify({'error': 'Missing fields'}), 400

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute("UPDATE products SET stock_count = %s WHERE id = %s", (new_stock, product_id))
        db.commit()
        return jsonify({'status': 'updated'})
    except Exception as e:
        app.logger.error(f"Update error: {e}")
        return jsonify({'error': 'Database error'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
